#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
# -*- coding: utf-8 -*-
"""lit_gapscan.py — 从知识库**自身的知识缺口**生成文献检索式。

为什么需要它
------------
`lit_discover.py` 是**关键词驱动**的：你得先想出查什么。
但知识库其实**自己就知道哪里有洞**——它记着：

| 信号 | 出处 | 含义 |
|---|---|---|
| `evidence_base: single-source` | concept/topic frontmatter | 该结论只有 1 篇一手源支撑 |
| `evidence_base: secondhand` | 同上 | 二手源占比 ≥1/3 |
| `si_status: missing / partial` **＋正文 SI 缺口标记** | source frontmatter/正文 | 缺补充材料，定量结论无法核验 |
| `> ⚠️ 单源论断：` | 正文标记 | 未获独立复现 |
| `> ⚠️ 无实验验证：` | 正文标记 | 纯计算结论，无合成/表征佐证 |
| `> ⚠️ 信息缺口：` | 正文标记 | 关键前提无从判定 |
| `## 诚实边界` 里的"待补/未核/未复现" | 正文 | 作者自陈的空白 |

本工具把这些信号翻成**可直接喂给 `lit_discover.py` 的检索式**，
并按「缺口严重度 × 该页重要性」排序 ⇒ 找文献从「我想查什么」变成「库缺什么」。

用法
----
    python tools/lit_gapscan.py                       # 缺口报告（按优先级）
    python tools/lit_gapscan.py --signals single-source,no-experiment
    python tools/lit_gapscan.py --top 15 --json       # 机器可读（供 Agent 消费）
    python tools/lit_gapscan.py --queries             # 只输出检索式（每行一条 + 出处注释）
    python tools/lit_gapscan.py --out <md|json>       # 另存本轮缺口记录（默认自动落盘）
    python tools/lit_gapscan.py --list-signals        # 信号口径说明（含 si-missing 的限度）
    python tools/lit_gapscan.py --selftest

落盘（「缺口驱动下一轮」必须留痕）
----------------------------------
默认写 `<runs_dir>/runs/gaps-<日期>.json`（`runs_dir` 来自 `lit_config.yaml`，
路径由 `kb_lib.lit_runs_dir` 派生，不写死）。**不覆盖上一轮**：目标已存在时自动加
`-HHMMSS` 后缀。`--out` 给 `.md` 则写人类可读渲染。`--no-out` 可完全不落盘（只打印）。

退出码
------
    0 = 正常
    1 = **降级**：`meta_full.json` 读不到 ⇒ 入度权重退化为 1.0，排序不反映重要性
        （结果仍可用，但必须知道它少了哪一维）
    2 = 参数错误或写盘失败

口径（详见 `--list-signals`）
-----------------------------
`si-missing` 只有一半可信：它要求 source 页 `si_status ∈ {missing, partial}` **且正文有
显式 SI 缺口标记**；同一页已有其它缺口时它**不独立计分**（避免同一处缺口被算两次）。
"""

import os
import re
import sys
import json
import datetime
import argparse
from collections import defaultdict

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import kb_lib as K
K.console_encoding()

# 🔴 import 期就装好 stdout/stderr 的编码守卫（Windows 控制台默认 GBK，中文/emoji 会
#    UnicodeEncodeError 把整条命令打断）。旧版只在 `__main__` 里装 ⇒ **被 import 时没有守卫**。
#    与 lit_discover / lit_fetch 保持一致，统一放模块级。

SIGNALS = {
    "single-source": "该结论只有单一一手源支撑，未获独立复现",
    "secondhand": "证据以二手转述为主，缺一手原文",
    "si-missing": "缺补充材料（SI），定量结论无法核验（口径见 --list-signals）",
    "single-claim": "正文标有『单源论断』",
    "no-experiment": "正文标有『无实验验证』（纯计算，无合成/表征佐证）",
    "info-gap": "正文标有『信息缺口』",
    "hedge-todo": "《诚实边界》自陈有待补/未核/未复现项",
}

MARKERS = {
    "single-claim": re.compile(r"单源论断|单源标记"),
    "no-experiment": re.compile(r"无实验验证"),
    "info-gap": re.compile(r"信息缺口"),
}
TODO_PAT = re.compile(r"待补|未核|未复现|尚待|有待|无法判定|无从判定|未做")
HONEST_SEC = re.compile(r"^##+\s*诚实边界.*$", re.M)

# SI 缺口的**正文证据**。
# 🔴 为什么必须有它：frontmatter 的 `si_status` 长期被 `lit_ingest` 对新卡一律硬写成
#    "missing"（见 tools/lit_ingest.py 的同轮修复说明），故**单凭该字段等于凭空造缺口**
#    （实测 299 条命中里 176 条正文一个字都没提 SI）。必须有正文的显式 SI 表述才算数：
#    `> ⚠️ 信息缺口：SI 未落库`、`**SI 缺失**`、精读时手写的 `si_status: missing` 等。
SI_GAP_PAT = re.compile(
    r"(?:SI|Supplementary|补充材料|补充信息)[^\n]{0,24}?"
    r"(?:缺失|未提供|未获取|未落库|不完全|不完整|未随提取件|不在提取件|无补充材料)"
    r"|si_status\s*[:=]\s*(?:missing|partial)",
    re.I)


def _has_hedge_todo(body):
    """《诚实边界》一节里是否自陈了待补/未核项。"""
    m = HONEST_SEC.search(body)
    if not m:
        return False
    return bool(TODO_PAT.search(body[m.end():m.end() + 1500]))


# ---------------------------------------------------------------- 扫描缓存（mtime 失效）
# 🔴 为什么要有缓存：`scan()` 会**全量读** concepts/topics/sources 三个目录的每个文件
#    （600+ 个 md，逐个 frontmatter 解析 + 4 条正则）。而"缺口驱动下一轮"是**每轮都跑**的
#    动作 ⇒ 每次都在重做同样的解析；旧 `--selftest` 更是整库扫 4 遍。
#    按 (mtime, size) 缓存**事实**（不是结论）：文件没动就直接复用，改过的才重解析。
_CACHE_OVERRIDE = ""      # 自检时指向临时文件，避免污染真实 state 目录
CACHE_VERSION = 1         # 结构一变就作废旧缓存（否则会读到缺字段的旧记录，静默用错事实）


def cache_path(cfg=None):
    """缓存落点：`<runs_dir>/state/gapscan_cache.json`（由配置派生，不写死路径）。"""
    if _CACHE_OVERRIDE:
        return _CACHE_OVERRIDE
    try:
        cfg = cfg or K.load_lit_config()
        return os.path.join(K.lit_runs_dir(cfg, "state"), "gapscan_cache.json")
    except Exception:                            # noqa: BLE001
        return ""


def _load_cache(path):
    if not path or not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            d = json.load(f)
        if int(d.get("version") or 0) != CACHE_VERSION:
            return {}
        return d.get("files") or {}
    except Exception:                            # noqa: BLE001
        return {}


def _save_cache(path, files):
    """原子落盘（tmp + os.replace）。

    🔴 非原子写的后果不止"缓存丢了"：被杀/断电留下**半截 JSON**，下次读失败会被当成
    "没有缓存"⇒ 静默重扫（慢但正确）；更糟的是某些结构下能解析出**缺字段的半条记录**
    ⇒ 用残缺事实生成缺口报告。故一律原子替换。
    """
    if not path:
        return
    tmp = path + ".tmp"
    try:
        d = os.path.dirname(path)
        if d:
            os.makedirs(d, exist_ok=True)
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"version": CACHE_VERSION,
                       "generated": datetime.datetime.now().isoformat(timespec="seconds"),
                       "files": files}, f, ensure_ascii=False)
        os.replace(tmp, path)
    except Exception as e:                       # noqa: BLE001
        sys.stderr.write(f"[warn] 写入缺口扫描缓存失败：{path} → {type(e).__name__}: {e}\n")


def _read_page(path, kind):
    """解析一页，抽出缺口判定所需的**事实**（与 --signals 过滤无关 ⇒ 可缓存）。"""
    text = K.read_text(path)
    fm_raw, body = K.split_frontmatter(text)
    fm = K.parse_frontmatter(fm_raw)
    aliases = fm.get("aliases") or []
    if isinstance(aliases, str):
        aliases = [aliases]
    return {
        "type": str(fm.get("type") or kind),
        "eb": str(fm.get("evidence_base") or "").strip().lower(),
        "si": str(fm.get("si_status") or "").strip().lower(),
        "si_marker": bool(SI_GAP_PAT.search(body)),
        "markers": [s for s, pat in MARKERS.items() if pat.search(body)],
        "hedge": _has_hedge_todo(body),
        "aliases": [str(a) for a in aliases],
    }


def load_indegree():
    """从 meta_full.json 取入度（衡量该页在库里的重要性）。

    返回 `(indeg, note)`：note 非空 = **降级**（入度全取不到，重要性权重退化为 1.0）。

    🔴 旧实现静默 `return defaultdict(int)`：meta_full.json 缺失/损坏/为空时，
    所有页面的权重都变成 1.0 —— **报告看不出任何异常，只是排序不再反映重要性**。
    与 CLAUDE.md「计数器本身出错却被读成内容质量问题」同型，故显式降级并上抛。
    """
    indeg = defaultdict(int)
    if not os.path.exists(K.FULL_PATH):
        return indeg, (f"meta_full.json 不存在（{K.FULL_PATH}）⇒ 重要性权重退化为 1.0、"
                       f"排序不反映入度；先跑 python tools/kb_build_index.py")
    try:
        with open(K.FULL_PATH, "r", encoding="utf-8") as f:
            pages = json.load(f).get("pages", {})
    except Exception as e:                       # noqa: BLE001
        return indeg, (f"meta_full.json 读取/解析失败（{type(e).__name__}: {e}）"
                       f"⇒ 重要性权重退化为 1.0")
    if not isinstance(pages, dict) or not pages:
        return indeg, f"meta_full.json 里 pages 为空（{K.FULL_PATH}）⇒ 重要性权重退化为 1.0"
    names = set(pages)
    for name, m in pages.items():
        for t in (m.get("out") or []):
            t = t.replace("\\", "/").split("/")[-1]
            if t.endswith(".md"):
                t = t[:-3]
            if t in names:
                indeg[t] += 1
    return indeg, ""


def scan(only=None, meta=None, cfg=None, use_cache=True, refresh=False):
    """扫描 wiki，返回缺口条目列表。

    meta（可选 dict）：回填本轮诊断——`degraded` / `degraded_reasons` /
    `cache_hits` / `cache_parsed` / `cache_path`。上层据此判降级退出码。
    """
    meta = meta if meta is not None else {}
    indeg, ind_note = load_indegree()
    meta["degraded_reasons"] = [ind_note] if ind_note else []
    meta["degraded"] = bool(ind_note)
    out = []

    def want(sig):
        return (not only) or (sig in only)

    cache_p = cache_path(cfg) if use_cache else ""
    cached = {} if (refresh or not use_cache) else _load_cache(cache_p)
    meta["cache_path"] = cache_p
    files_cache = {}
    n_hit = n_parsed = 0

    for kind, d in (("concept", "concepts"), ("topic", "topics"),
                    ("source", "sources")):
        full = os.path.join(K.WIKI, d)
        if not os.path.isdir(full):
            continue
        for f in sorted(os.listdir(full)):
            if not f.endswith(".md"):
                continue
            page = f[:-3]
            path = os.path.join(full, f)
            try:
                st = os.stat(path)
                # 缓存键用**绝对路径**（不用 relpath：临时夹具 vault 可能在别的盘符上，
                #  `relpath` 跨盘会直接 ValueError——自检必崩）
                key = os.path.abspath(path).replace("\\", "/")
            except OSError:
                continue
            rec = cached.get(key)
            if (rec and rec.get("mtime") == st.st_mtime
                    and rec.get("size") == st.st_size):
                n_hit += 1
            else:
                rec = _read_page(path, kind)
                n_parsed += 1
                rec["mtime"] = st.st_mtime
                rec["size"] = st.st_size
            files_cache[key] = rec
            hits = []

            # ---- frontmatter 信号
            eb = rec["eb"]
            if kind in ("concept", "topic"):
                if eb == "single-source" and want("single-source"):
                    hits.append(("single-source", 3.0))
                if eb == "secondhand" and want("secondhand"):
                    hits.append(("secondhand", 2.0))
            si = rec["si"]
            # 🔴 **双条件**才算 SI 缺口（frontmatter si_status + 正文显式标记）。
            #    旧实现只看 `si_status ∈ {missing,partial}`，而 lit_ingest 建卡时对该字段
            #    一律硬写 "missing" ⇒ 该信号长期在**制造**缺口。只有正文也说了才算数。
            if (kind == "source" and si in ("missing", "partial")
                    and rec["si_marker"] and want("si-missing")):
                hits.append(("si-missing", 2.0 if si == "missing" else 1.2))

            # ---- 正文标记
            for sig in rec["markers"]:
                if want(sig):
                    hits.append((sig, 1.5))

            # ---- 诚实边界里的待办
            if rec["hedge"] and want("hedge-todo"):
                hits.append(("hedge-todo", 1.0))

            if not hits:
                continue

            # 🔴 si-missing **不独立计分**：同一页已有其它缺口时，它只是补充说明。
            #    否则"单源论断 + SI 缺失"这类页面会把同一处信息不足算两遍，优先级虚高。
            #    信号仍保留在列表里，只是权重归 0 并附注（读报告的人看得见它存在）。
            si_merged = (any(s == "si-missing" for s, _ in hits) and len(hits) > 1)
            if si_merged:
                hits = [(s, 0.0 if s == "si-missing" else w) for s, w in hits]

            ptype = rec["type"] or kind
            base = sum(w for _, w in hits)
            # 重要性加权：入度越高，缺口越值得优先补
            prio = base * (1.0 + min(indeg.get(page, 0), 60) / 20.0)

            # ---- 检索式：优先用**英文别名**（OpenAlex 对英文关键词的召回远好于中文页名）
            alias_strs = rec["aliases"]
            en = [a for a in alias_strs if re.search(r"[A-Za-z]{3,}", a)]
            # 只有**一个英文别名都取不到**时才退回页名。
            #   source 页名形如「2026-物理引导描述符预测电池库仑效率-AdvSci」，
            #   它是卡片名而非检索词；把这种中文长串塞进 OpenAlex 只会稀释召回。
            raw_terms = en[:3] if en else [page]
            # 去重保序：页名与其别名常互为子串，不去重会出现
            # 「Yaghi组网状化学AI4S Yaghi组网状化学AI4S」这种重复检索式
            terms, seen_t = [], set()
            for t in raw_terms:
                t = re.sub(r"\s+", " ", str(t)).strip()
                key = t.lower()
                if t and key not in seen_t:
                    seen_t.add(key)
                    terms.append(t)
            query = " ".join(terms)

            reasons = []
            for s, _w in hits:
                txt = SIGNALS.get(s, s)
                if s == "si-missing" and si_merged:
                    txt += "（并入本页其它缺口，不重复计分）"
                reasons.append(txt)

            out.append({
                "query": query,
                "page": page,
                "path": f"wiki/{d}/{f}",
                "type": ptype,
                "signals": [s for s, _ in hits],
                "reasons": reasons,
                "priority": round(prio, 2),
                "in_degree": indeg.get(page, 0),
                "evidence_base": eb or None,
                "aliases": alias_strs[:5],
                "si_merged": si_merged,
            })
    if use_cache:
        _save_cache(cache_p, files_cache)
    meta["cache_hits"] = n_hit
    meta["cache_parsed"] = n_parsed
    out.sort(key=lambda x: -x["priority"])
    return out


def report(items, top=25):
    print("=" * 68)
    print("  知识缺口 → 文献检索式")
    print("=" * 68)
    print(f"共发现 {len(items)} 处缺口（按 缺口严重度 × 页面重要性 排序）\n")
    for i, it in enumerate(items[:top], 1):
        print(f"{i:>2}. [prio {it['priority']:>6.2f}] [{it['type']}] {it['page']}"
              f"   (入度 {it['in_degree']})")
        print(f"    检索式: {it['query']}")
        print(f"    缺口  : {'；'.join(it['reasons'])}")
        print(f"    出处  : {it['path']}")
        print()
    if len(items) > top:
        print(f"… 其余 {len(items) - top} 条用 --top N 查看")
    print("下一步：把检索式交给 lit_discover.py，例如")
    if items:
        print(f'  python tools/lit_discover.py "{items[0]["query"]}" 近一个月 --limit 20')
    return 0


def render_markdown(items, top=25, meta=None):
    """人类可读渲染（`--out *.md` 用）。"""
    meta = meta or {}
    L = [f"# 知识缺口 → 文献检索式 · {datetime.date.today().isoformat()}", ""]
    L.append(f"> 共 {len(items)} 处缺口（按 缺口严重度 × 页面重要性 排序）；"
             f"本文件是「缺口驱动下一轮」的记录。")
    L.append("> 🔴 `si-missing` 只有一半可信：需 `si_status ∈ {missing,partial}` **且**正文有"
             "显式 SI 缺口标记；同一页已有其它缺口时不独立计分。")
    for r in meta.get("degraded_reasons") or []:
        L.append(f"> ⚠️ **降级运行**：{r}")
    L.append("")
    for i, it in enumerate(items[:top], 1):
        L.append(f"## {i}. [{it['type']}] {it['page']}（prio {it['priority']}，"
                 f"入度 {it['in_degree']}）")
        L.append("")
        L.append(f"- **检索式**：`{it['query']}`")
        L.append(f"- **缺口**：{'；'.join(it['reasons'])}")
        L.append(f"- **出处**：`{it['path']}`")
        L.append("")
    if len(items) > top:
        L.append(f"… 其余 {len(items) - top} 条见 JSON 版（`--out *.json`）或用 `--top N` 查看。")
    return "\n".join(L) + "\n"


def _nonclobber(path):
    """不覆盖上一轮产物：目标已存在则加 `-HHMMSS`（同日多次运行各自留档）。"""
    p = path
    if not os.path.exists(p):
        return p
    stem, ext = os.path.splitext(p)
    return f"{stem}-{datetime.datetime.now().strftime('%H%M%S')}{ext}"


def write_out(items, path, top=25, meta=None):
    """把本轮缺口记录落盘（按扩展名选 json / md）。返回实际写入的路径。"""
    meta = meta or {}
    actual = _nonclobber(path)
    d = os.path.dirname(actual)
    if d:
        os.makedirs(d, exist_ok=True)
    if os.path.splitext(actual)[1].lower() == ".md":
        text = render_markdown(items, top=top, meta=meta)
    else:
        payload = {"generated": datetime.datetime.now().isoformat(timespec="seconds"),
                   "count": len(items),
                   "shown": min(top, len(items)),
                   "degraded": bool(meta.get("degraded")),
                   "degraded_reasons": meta.get("degraded_reasons") or [],
                   "cache": {"path": meta.get("cache_path"),
                             "hits": meta.get("cache_hits"),
                             "parsed": meta.get("cache_parsed")},
                   "items": items}
        text = json.dumps(payload, ensure_ascii=False, indent=1)
    # 原子落盘：半截 JSON 会被下一轮当成"上一轮记录"读（且 json.loads 失败后无人知道原因）
    tmp = actual + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text)
    os.replace(tmp, actual)
    return actual


def selftest():
    """自检：**全部在合成夹具 vault 上做**，不扫真库。

    🔴 为什么要改：旧自检对真库 `scan()` 了 **4 遍**（每次都全量读 concepts/topics/sources
    600+ 个文件），既慢，又把「当前库内容」当断言——库一变、自检结果就变，而它守的其实是
    **代码逻辑**（过滤、合并、去重、排序）。现在用临时 vault + 临时缓存落点，结论与真库无关。
    """
    print("=== lit_gapscan --selftest ===")
    ok = True

    def chk(label, cond, extra=""):
        nonlocal ok
        print(f"  [{'ok' if cond else 'FAIL'}] {label}"
              f"{(' -> ' + str(extra)) if extra != '' else ''}")
        ok = ok and bool(cond)

    import shutil
    import tempfile
    # 临时目录**不得落在库根**（旧版写 `HERE/_selftest_probe_*`，被杀就留垃圾，
    # 也会被 kb_toolcheck 的写盘防呆判成"意外写盘"）。逐级回退 + 实写探测。
    tmp = ""
    for base in (tempfile.gettempdir(), os.getcwd(), HERE):
        cand = os.path.join(base, "_litwatch-selftest-gapscan")
        try:
            shutil.rmtree(cand, ignore_errors=True)
            os.makedirs(cand, exist_ok=True)
            with open(os.path.join(cand, ".probe"), "w", encoding="utf-8") as f:
                f.write("x")
            os.remove(os.path.join(cand, ".probe"))
            tmp = cand
            break
        except OSError:
            continue
    if not tmp:
        print("  [FAIL] 无法创建自检临时目录")
        return 1

    def _write(rel, text):
        p = os.path.join(tmp, *rel.split("/"))
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", encoding="utf-8") as f:
            f.write(text)
        return p

    # ---- 夹具 vault：覆盖六种信号，含 si-missing 的正/反例 ----
    _write("wiki/concepts/锌负极.md",
           "---\ntype: concept\nevidence_base: single-source\n"
           "aliases: [zinc anode, Zn deposition]\n---\n\n# 锌负极\n\n"
           "> ⚠️ 单源论断：界面成核势垒仅一篇一手源支撑。\n")
    # 反例 A：lit_ingest 硬写的 si_status，正文**没有**任何 SI 表述 ⇒ 不得算缺口
    _write("wiki/sources/2026-夹具A-只硬写字段.md",
           "---\ntype: source\nsi_status: missing\n---\n\n# 夹具 A\n\n正文不提补充材料。\n")
    # 正例 B：正文确有 SI 缺口表述，且**没有**其它缺口 ⇒ 独立计分
    _write("wiki/sources/2026-夹具B-真缺SI.md",
           "---\ntype: source\nsi_status: missing\n---\n\n# 夹具 B\n\n"
           "SI 未落库，定量结论无法核验。\n")
    # 正例 C：有 SI 缺口**且**有其它缺口（信息缺口）⇒ 合并，不重复计分
    _write("wiki/sources/2026-夹具C-缺SI且有其它缺口.md",
           "---\ntype: source\nsi_status: missing\n---\n\n# 夹具 C\n\n"
           "> ⚠️ 信息缺口：SI 未落库，关键参数无从判定。\n")
    # 正例 D：诚实边界里的待补项
    _write("wiki/concepts/夹具D-诚实边界.md",
           "---\ntype: concept\nevidence_base: mixed\naliases: [hedge probe]\n---\n\n"
           "# 夹具 D\n\n## 诚实边界\n\n- 界面模型参数待补。\n")
    # 反例 E：完全干净的页面（无任何信号）
    _write("wiki/sources/2026-夹具E-干净.md",
           "---\ntype: source\nsi_status: present\n---\n\n# 夹具 E\n\n无缺口。\n")
    full_p = os.path.join(tmp, "meta_full.json")
    with open(full_p, "w", encoding="utf-8") as f:
        json.dump({"pages": {p: {"out": []} for p in
                             ("锌负极", "2026-夹具A-只硬写字段", "2026-夹具B-真缺SI",
                              "2026-夹具C-缺SI且有其它缺口", "夹具D-诚实边界",
                              "2026-夹具E-干净")}}, f)

    real = (K.WIKI, K.FULL_PATH, globals()["_CACHE_OVERRIDE"])
    cache_f = os.path.join(tmp, "state", "gapscan_cache.json")
    try:
        K.WIKI = os.path.join(tmp, "wiki")
        K.FULL_PATH = full_p
        globals()["_CACHE_OVERRIDE"] = cache_f

        meta = {}
        items = scan(meta=meta, cfg={})
        chk("夹具 vault：扫出缺口条目", len(items) >= 1, len(items))
        pages = {it["page"]: it for it in items}
        # 反例：只硬写 si_status 的页面**不得**进缺口列表
        chk("反例 A：仅 si_status:missing（正文无 SI 表述）不算缺口",
            "2026-夹具A-只硬写字段" not in pages)
        # 正例 B：正文有 SI 表述 ⇒ 独立计分（2.0 × 无入度加权 = 2.0）
        b = pages.get("2026-夹具B-真缺SI") or {}
        chk("正例 B：正文有 SI 表述 ⇒ si-missing 独立计分",
            b.get("signals") == ["si-missing"] and b.get("si_merged") is False
            and abs(b.get("priority", 0) - 2.0) < 1e-6,
            f"{b.get('signals')} prio={b.get('priority')}")
        # 正例 C：与其它缺口同页 ⇒ 并入、不重复计分（权重只剩 info-gap 的 1.5）
        c = pages.get("2026-夹具C-缺SI且有其它缺口") or {}
        chk("正例 C：同页有其它缺口 ⇒ si-missing 并入不重复计分",
            c.get("si_merged") is True and "si-missing" in (c.get("signals") or [])
            and abs(c.get("priority", 0) - 1.5) < 1e-6,
            f"{c.get('signals')} prio={c.get('priority')}")
        chk("正例 C：理由里写明了并入", any("并入" in r for r in (c.get("reasons") or [])))
        # 反例 E：干净页面不得出现
        chk("反例 E：无信号页面不出现在结果里", "2026-夹具E-干净" not in pages)
        # 正例 D：诚实边界 → hedge-todo
        d = pages.get("夹具D-诚实边界") or {}
        chk("正例 D：《诚实边界》待补项 → hedge-todo",
            "hedge-todo" in (d.get("signals") or []), d.get("signals"))
        # 正例：结果按 priority 降序
        ps = [x["priority"] for x in items]
        chk("按优先级降序排列",
            all(ps[i] >= ps[i + 1] for i in range(len(ps) - 1)), ps)
        # 每条必须有 query/reason；英文别名优先
        chk("每条都含检索式与缺口理由",
            all(x["query"].strip() and x["reasons"] for x in items))
        z = pages.get("锌负极") or {}
        chk("检索式优先取英文别名", "zinc anode" in (z.get("query") or ""), z.get("query"))
        chk("frontmatter + 正文两类信号都命中",
            {"single-source", "single-claim"} <= set(z.get("signals") or []),
            z.get("signals"))
        # 反例：限定一个绝不存在的信号 → 必须得到 0 条
        empty = scan(only=["__不存在的信号__"], cfg={})
        chk("反例 不存在的信号返回 0 条", len(empty) == 0, len(empty))
        # 反例：单信号过滤必须真过滤（子集）
        sub = scan(only=["single-source"], cfg={})
        chk("单信号过滤是子集",
            all("single-source" in x["signals"] for x in sub) and len(sub) <= len(items),
            f"{len(sub)} ⊆ {len(items)}")
        # 降级：FULL_PATH 指向不存在 → 必须显式报降级（而非静默权重 1.0）
        K.FULL_PATH = os.path.join(tmp, "不存在.json")
        meta2 = {}
        scan(only=["single-source"], meta=meta2, cfg={})
        chk("反例 meta_full 缺失 ⇒ 标记降级",
            meta2.get("degraded") is True and meta2.get("degraded_reasons"),
            meta2.get("degraded_reasons"))
        K.FULL_PATH = full_p
        # 缓存：第一遍解析、第二遍命中、--refresh 强制重解析
        meta3 = {}
        scan(meta=meta3, cfg={})
        chk("缓存：第二遍全部命中缓存（不再解析）",
            meta3.get("cache_parsed") == 0 and meta3.get("cache_hits") >= 1,
            f"hits={meta3.get('cache_hits')} parsed={meta3.get('cache_parsed')}")
        chk("缓存文件已原子落盘且无 .tmp 残留",
            os.path.exists(cache_f) and not os.path.exists(cache_f + ".tmp"))
        meta4 = {}
        scan(meta=meta4, cfg={}, refresh=True)
        chk("--refresh 强制重解析", meta4.get("cache_parsed") >= 1,
            f"parsed={meta4.get('cache_parsed')}")
        # 落盘：默认产物名不覆盖上一轮（同日多次运行加时间戳）
        out_p = os.path.join(tmp, "runs", "gaps.json")
        p1 = write_out(items, out_p, meta=meta)
        p2 = write_out(items, out_p, meta=meta)
        chk("产物不覆盖上一轮（同名自动加时间戳）", p1 != p2 and os.path.exists(p1)
            and os.path.exists(p2), f"{os.path.basename(p1)} / {os.path.basename(p2)}")
        chk("产物可被 json 读回且条数一致",
            len(json.load(open(p1, encoding="utf-8"))["items"]) == len(items))
        md_p = write_out(items, os.path.join(tmp, "runs", "gaps.md"), meta=meta)
        chk("--out *.md 走人类可读渲染",
            open(md_p, encoding="utf-8").read().startswith("# 知识缺口"))
    finally:
        K.WIKI, K.FULL_PATH, globals()["_CACHE_OVERRIDE"] = real
        shutil.rmtree(tmp, ignore_errors=True)

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="知识缺口 → 文献检索式")
    ap.add_argument("--signals", default="",
                    help="只看指定信号，逗号分隔：" + ",".join(SIGNALS))
    ap.add_argument("--top", type=int, default=25)
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--queries", action="store_true",
                    help="只输出检索式（每行一条，紧随一行 `# 出处…` 注释）")
    ap.add_argument("--out", default="",
                    help="另存本轮记录：.json（完整）或 .md（人读）。"
                         "默认 <runs_dir>/runs/gaps-<日期>.json；不覆盖已存在的上一轮文件")
    ap.add_argument("--no-out", action="store_true", help="不落盘，只打印")
    ap.add_argument("--no-cache", action="store_true",
                    help="不使用 mtime 缓存（强制全量重解析）")
    ap.add_argument("--list-signals", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        return selftest()

    try:
        cfg = K.load_lit_config()
    except Exception as e:                       # noqa: BLE001
        sys.stderr.write(f"[warn] lit 配置读取失败（{type(e).__name__}: {e}），"
                         f"改用内置默认路径\n")
        cfg = {}

    if args.list_signals:
        print("缺口信号口径")
        for k, v in SIGNALS.items():
            print(f"  {k:<16} {v}")
        print("")
        print("  ⚠️ si-missing 只有一半可信：它要求 source 页 `si_status` ∈ {missing, partial}"
              " **且**正文出现显式 SI 缺口标记")
        print("     （如 `信息缺口：SI 未落库` / `SI 缺失`）。只凭 frontmatter 会**造缺口**——")
        print("     lit_ingest 曾对新卡一律硬写 si_status: missing（该字段本身不是证据）。")
        print("  ⚠️ 同一页已有其它缺口时，si-missing **不独立计分**（并入上方缺口），")
        print("     避免同一处信息不足被算两遍、优先级虚高。")
        return 0

    only = [s.strip() for s in args.signals.split(",") if s.strip()] or None
    meta = {}
    items = scan(only=only, meta=meta, cfg=cfg, use_cache=not args.no_cache)

    degraded = bool(meta.get("degraded"))
    if degraded:
        # 🔴 降级必须被读出来：入度取不到时排序不反映重要性，而报告表面完全正常。
        sys.stderr.write("[warn] 降级运行：" + "；".join(meta.get("degraded_reasons") or [])
                         + "\n")

    # ---- 落盘：缺口驱动下一轮必须留痕（默认 json，不覆盖上一轮）----
    out_path = None
    if not args.no_out:
        if args.out:
            target = args.out
        else:
            # 默认落点由配置派生（`<runs_dir>/runs/gaps-<日期>.json`）。
            # ⚠️ 配置缺 runs_dir 时 kb_lib 给的是**相对**默认值 ⇒ 必须挂到库根上，
            #    否则产物会写进"当前工作目录"，而本库脚本允许在别处调用（库根由 __file__ 推导）。
            d = K.lit_runs_dir(cfg or {}, "runs")
            if not os.path.isabs(d):
                d = os.path.join(K.VAULT, *d.replace("\\", "/").split("/"))
            target = os.path.join(d, f"gaps-{datetime.date.today().isoformat()}.json")
        if not os.path.splitext(target)[1]:
            target += ".json"
        try:
            out_path = write_out(items, target, top=args.top, meta=meta)
        except Exception as e:                   # noqa: BLE001
            sys.stderr.write(f"[!] 缺口记录写盘失败：{target} → {type(e).__name__}: {e}\n")
            return 2

    if args.queries:
        seen = set()
        for it in items:
            q = it["query"]
            if q in seen:
                continue
            seen.add(q)
            print(q)
            # 🆕 出处注释：旧版只打印检索式，**看不出这条是从哪一页、哪个信号来的**
            #    ⇒ 下一轮无法回溯「这个检索式为什么会出现」。
            print(f"# 出处: {it['path']} ｜ 信号: {','.join(it['signals'])}"
                  f" ｜ prio: {it['priority']}")
        if out_path:
            sys.stderr.write(f"\n缺口记录已写入: {out_path}\n")
        return 1 if degraded else 0
    if args.json:
        print(json.dumps({"count": len(items), "degraded": degraded,
                          "degraded_reasons": meta.get("degraded_reasons") or [],
                          "out": out_path,
                          "items": items[:args.top]},
                         ensure_ascii=False, indent=1))
        return 1 if degraded else 0

    report(items, top=args.top)
    if out_path:
        print(f"缺口记录已写入: {out_path}")
    if degraded:
        print("[!] 本轮为降级运行（入度权重未生效）⇒ 退出码 1")
    return 1 if degraded else 0


if __name__ == "__main__":
    # 🔴 必须 `sys.exit(main())`：直接调用 main() 会丢掉返回值 ——
    #    自检 FAIL / 降级 / 写盘失败都变成退出码 0，等于没有判据。
    sys.exit(main())
